import{_ as i,o as t,c as s,a2 as l}from"./chunks/framework.Cms9CC3y.js";const a="/entislng/v5/assets/0c7ab61455073a7d-20261015000317-9i2w7g1.tvcosOYc.png",c="/entislng/v5/assets/aa5bc81f4ae82027-20261015000317-7pnhl7x.Cw-FrvQu.png",r="data:image/png;base64,",e="data:image/png;base64,",g="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABYAAAAcCAIAAADqTdgKAAAAAXNSR0IArs4c6QAAAARnQU1BAACxjwv8YQUAAAAJcEhZcwAADsMAAA7DAcdvqGQAAABRSURBVEhL7cxBCgAgCERRb98lvUtJCRJYmUK08G+UWTzAcFC8MUBEdaUQAza2JHg4lYSUhJSE9IqAnvpQr4h9/xP2dOK2ieiuJwaI4BsoTCA2WcW9mGEUA0cAAAAASUVORK5CYII=",h=JSON.parse('{"title":"罐计算器","description":"","frontmatter":{"title":"罐计算器","date":"2026-10-14T16:03:17.000Z","lastmod":"2026-11-24T18:35:36.000Z"},"headers":[],"relativePath":"guide/1222.md","filePath":"guide/帮助文档/操作说明/罐监控操作/罐计算器.md"}'),o={name:"guide/1222.md"};function n(p,A,d,U,m,E){return t(),s("div",null,[...A[0]||(A[0]=[l('<h1 id="罐计算器" tabindex="-1">罐计算器 <a class="header-anchor" href="#罐计算器" aria-label="Permalink to &quot;罐计算器&quot;">​</a></h1><p><strong>摘要</strong>：实现罐量计算</p><ul><li>通过基础液位，温度，密度数据计算体积和质量</li><li>通过输入质量和体积，倒算液位（此计算不是精确计算，会有估算部份，所以会有误差）</li><li>通过前尺，后尺数据计算变化量，</li><li>通过前尺和变化量数据计算后尺</li></ul><p><strong>1：如何进入</strong></p><p>点击菜单【罐监控操作】下面的【罐计算器】按钮，如图：</p><p><img src="'+a+'" alt=""></p><p><strong>2:如何使用</strong></p><p>主界面如下图：</p><p><img src="'+c+'" alt=""></p><ol><li><img src="'+r+'" alt=""></li><li><img src="'+e+'" alt=""></li><li><img src="'+g+'" alt=""></li><li>计算规则：</li><li>在【前尺】输入值并计算后，【前尺】的相应计算量如体积和质量会发生变化，同时会根据【前尺】和【后尺】的数据进行变化更新中间【变化】部分。</li><li>在中间【变化】部分输入值后，不会影响【前尺】数据，会根据【前尺】和【变化】的数据计算更新【后尺】数据。</li><li>在【后尺】输入值并计算后，不会影响【前尺】数据，会根据【前尺】和【后尺】的数据计算更新【变化】部分数据。</li></ol><p><strong>3:其他说明</strong></p><ul><li>【变化】中的到限时间根据进出罐区分，如进罐则表示到达最大安全容量时的时间，如出罐则表示到达最小安全容量时的时间</li><li>【变化】中的标密是【前尺】和【后尺】的变化部份</li><li>在罐计算器中进行计算时，会按照选择罐在系统中的配置进行计算，所以相关计算值请参考罐的计算参数配置，如是否开启水份计算，是否开启罐壁修正</li></ul>',12)])])}const B=i(o,[["render",n]]);export{h as __pageData,B as default};
